#include "postquantiquecoin/blockchain/ChainValidation.h"
namespace pqc { Result<uint64_t> ChainValidation::CalculateFees(const Block& block,const UTXOSet& view,uint64_t height,uint64_t maturity){ uint64_t fees=0; for(size_t i=1;i<block.transactions.size();++i){ const auto& tx=block.transactions[i]; uint64_t inSum=0; for(const auto& in:tx.inputs){ auto u=view.GetUTXO(in.previousTxid,in.outputIndex); if(!u) return Result<uint64_t>::Err("missing fee input"); if(!u->IsSpendable(height,maturity)) return Result<uint64_t>::Err("immature fee input"); if(UINT64_MAX-inSum<u->amountAtoms) return Result<uint64_t>::Err("fee input overflow"); inSum+=u->amountAtoms; } uint64_t out=tx.GetOutputSum(); if(inSum<out) return Result<uint64_t>::Err("negative fee"); if(UINT64_MAX-fees<inSum-out) return Result<uint64_t>::Err("fee overflow"); fees+=inSum-out; } return Result<uint64_t>::Ok(fees); } uint64_t ChainValidation::CoinbaseOutputSum(const Block& block){ uint64_t s=0; if(block.transactions.empty()) return 0; for(const auto& o:block.transactions[0].outputs) if(UINT64_MAX-s>=o.amountAtoms) s+=o.amountAtoms; return s; } }
